import {itemList} from '../datas/itemList';
import '../styles/ShoppingList.css';
import Item from './Item';
// const itemList = ['t-shirt', 'pull', 'pantalon', 'short', 'jupe'];


function ShoppingList() {
  return (
    <div className="shopping-list">
      <ul>
        {itemList.map((item) => (
          <li className='item'>
            {item.name} 
            onSale={item.onSale}
            {item.price} €
            < Item size={item.size}/>

            <Item
                cover={item.cover}
                name={item.name}
                size={item.size}
                comfort={item.comfort}
                price={item.price}
                onSale={item.onSale && <span>En soldes !</span>}
                />
          </li>
        ))}
      </ul>
    </div>
  )
}


export default ShoppingList
